// Avatar + AvatarGroup — Zaytona BRANDED avatar system.
// The default identity image is one of the Zaytona brand mascot characters
// (inlined below as data URIs so the component is fully self-contained and
// path-independent). There is NO letter/initials fallback — every avatar is a
// branded character. Pass `src` to use a specific image, or `character` (1-5)
// to pick a mascot explicitly; otherwise a mascot is chosen deterministically
// from `name`.
const BRAND_CHARACTERS = [
  'data:image/png;base64,', // av-1
  'data:image/png;base64,', // av-2
  'data:image/png;base64,', // av-3
  'data:image/png;base64,', // av-4
  'data:image/png;base64,', // av-5
];

/** Deterministic mascot index (0-4) from a name string. */
function _characterFor(name) {
  const s = String(name);
  let h = 0;
  for (let i = 0; i < s.length; i++) h += s.charCodeAt(i);
  return h % BRAND_CHARACTERS.length;
}

export function Avatar({ name = '', src, character, size = 44, ring = 'var(--navy)', style = {} }) {
  const img = src
    || BRAND_CHARACTERS[character != null ? (character - 1 + BRAND_CHARACTERS.length) % BRAND_CHARACTERS.length : _characterFor(name)];
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: size, height: size, flex: 'none',
      borderRadius: 'var(--radius-pill)', background: 'var(--surface-sunken)', border: `2px solid ${ring}`, overflow: 'hidden', ...style }}>
      <img src={img} alt={name} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
    </span>
  );
}

export function AvatarGroup({ children, max = 4, size = 36, style = {} }) {
  const items = React.Children.toArray(children);
  const shown = items.slice(0, max);
  const extra = items.length - shown.length;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', ...style }}>
      {shown.map((ch, i) => <span key={i} style={{ marginInlineStart: i === 0 ? 0 : -size * 0.32, zIndex: i }}>{React.cloneElement(ch, { size })}</span>)}
      {extra > 0 && <span style={{
        marginInlineStart: -size * 0.32, width: size, height: size, borderRadius: 'var(--radius-pill)',
        background: 'var(--navy)', color: 'var(--cream)', border: '2px solid var(--cream)',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
        fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: Math.round(size * 0.34), zIndex: 99 }}>+{extra}</span>}
    </span>
  );
}
